head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vScrenTpCD = "";
scwin.vBzProcsNo = "";
scwin.vIsurCd = ""; // 발행회사코드
scwin.vIsuCd = ""; // 종목코드
scwin.vIsuNm = ""; // 종목명
scwin.vIsuAbbrv = ""; // 종목약명
scwin.vAcptNo = ""; // 접수번호
scwin.v_SaveKind = "";
// 세션정보를 얻기위한 함수사용

scwin.fn_GetPar, scwin.fn_SetPar;

scwin.TR_JOB;
scwin.vSYMBL_INPUT_CD;
scwin.vSecuGrpId;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        let parentWin = $c.frame.path("../");
        scwin.vSecuGrpId = parentWin.fr_SecuGrpId;

        //
        $c.libRoundPanel.PanelToGroupBox(panel_Item);

        /* buttonSet의 초기화를 수행한다.  각 용도에 맞게 이미지ID와 onclick event시 수행할 function을 지정한다. */
        buttonSet.setSaveInfo(btn_Save, scwin.save); // 저장

        /*
        if (vSecuGrpId == SECUGRP_ID_EN) {
        	txb_memo.disabled = false;
        	txb_memo.value = "(미입력시 '변경전' 값이 저장됩니다.)";
        } else {
        	txb_memo.disabled = true;
        }
         */

        // Parent Data
        scwin.v_SaveKind = parentWin.vIsuNmChgApplKind; // Transaction 구분: 신규(N), 수정(U)
        // v_UpdParam = parentWin.v_UpdItmIsurParam;    //변경상장내역 Param

        if (scwin.v_SaveKind === "N") {
            scwin.vBzProcsNo = ""; // 업무처리번호
            scwin.vIsuCd = parentWin.clickIsuCd; // 종목코드   getObjectValue(parentWin.txb_SearchIsuCd2);
            scwin.vAcptNo = parentWin.clickAcptNo; // 접수번호

        }

        // 데이터 조회
        await scwin.selectReadInit();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08025.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08025.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name dts_Isu_OnLoadError
 * @description dts_Isu 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Isu_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_Isu);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08025.dts_Isu_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_Isu_OnLoadCompleted
 * @description dts_Isu 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Isu_OnLoadCompleted = function(rowcount) {

};

/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {void}
 * @hidden N
 */
scwin.trs_Save_OnFail = function() {
    try {
        $c.lce.fn_alertMsg('F');
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF08025.trs_Save_OnFail" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        $c.lce.fn_alertMsg('S');

        // Refresh Parent Frame
        scwin.parentRefresh();

        // 닫기
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08025.trs_Save_OnSuccess" });
    }
};

/**
 * @method
 * @name img_CHG_LIST_DD_onclick
 * @description img_CHG_LIST_DD 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_CHG_LIST_DD_onclick = function() {
    try {
        // 변경상장일 달력클릭
        popUpCalendar2(edt_CHG_LIST_DD);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF08025.img_CHG_LIST_DD_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name selectReadInit
 * @description 종목명변경 상장내역 조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.selectReadInit = async function() {
    let url = "";
    let srvMethod = "selectIsuNmChgApplDetail";
    url += "&SCREN_ID=" + "ULDSTF08025.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&ACPT_NO=" + scwin.vAcptNo;
    const sbmOptions = {
        id : "sbm_dts_Isu",
        action : "/etn/EtnChgList.do",
        ref : "",
        target : "dts_Isu=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // 발행기관코드 (parent에서 얻어올 수도 있음.
    // 저장시 필요함.
    scwin.vIsurCd = dts_Isu.getCellData(1, "ISUR_CD");
    scwin.vIsuNm = dts_Isu.getCellData(1, "ISU_NM");
    scwin.vIsuAbbrv = dts_Isu.getCellData(1, "ISU_ABBRV");
};

/**
 * @method
 * @name trs
 * @description 트랜잭션 처리 구분(저장,수정,삭제)
 * @param {*} trsIdx trsIdx
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs = async function(trsIdx) {
    let srvMethod = "";
    let trsKind;
    if (scwin.TR_JOB === 'I') {
        // Form 설정
        scwin.setFormField();
        scwin.vScrenTpCD = SCREN_PROCS_TP_CD_02;
        srvMethod = "insertIsuNmApplDtl";
        trsKind = TR_JOB_INSERT;
        trs_Save.KeyName = "toinb_dataid4";
        // [전환검토] trs_Save.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
        // const sbmParams = {
        //     TRS_IDX : trsKind,
        //     LIST_BZ_TP_CD : scwin.VListBzTpCd,
        //     LD_MKT_TP_CD : "1",
        //     TRANSTR_EMP_NO : js_emp_no,
        //     BZ_PROCS_NO : scwin.vBzProcsNo,
        //     ISUR_CD : scwin.vIsurCd,
        //     ISU_CD : scwin.vIsuCd,
        //     ACPT_NO : scwin.vAcptNo
        // };
        const sbmOptions = {
            id : "sbm_trs_Save",
            action : "/etn/EtnChgList.do",
            ref : "dts_Isu",
            target : "trs_Save=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

/**
 * @method
 * @name dupCheck
 * @description 종목 중복날짜 체크
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dupCheck = async function() {
    const chgDd = edt_CHG_LIST_DD.getValue();
    let isNotDup = true;
    url += "&SCREN_ID=" + "ULDSTF08025.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&ISU_CD=" + scwin.vIsuCd + "&CHG_DD=" + chgDd;
    const sbmOptions = {
        id : "sbm_dts_DupChk",
        action : "/etn/EtnChgList.do",
        ref : "",
        target : "dts_DupChk=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    if (dts_DupChk.getRowCount() > 0) {
        isNotDup = false;
        await $c.win.alert("동일한 날짜에 변경상장 지정된 종목이 존재합니다.");
    }
    return isNotDup;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name checkForm
 * @description Form Validation Check
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkForm = async function() {
    const vCurDate = $c.ut.cGetToday("yyyymmdd");
    if (scwin.vIsuCd === "") {
        await $c.win.alert("[종목]이 조회되어 있지 않습니다.");
        return false;
    }
    if (edt_CHG_LIST_DD.getValue() === "") {
        await $c.win.alert("[변경상장일]을 입력하세요.");
        edt_CHG_LIST_DD.focus();
        return false;
    }

    // 병합비율, 분할비율 둘다 값이 없을때는 종목명 변경으로 인식
    // Check Max Length
    if (txb_AFCHG_ISU_NM.getValue() !== "") {
        if (Number($c.stf.getStringSize(txb_AFCHG_ISU_NM.getValue())) > 1) {
            if (!$c.stf.checkMaxLength(txb_AFCHG_ISU_NM, 80, "한글종목명")) return false;
        }
    }
    if (txb_AFCHG_ISU_ABBRV1.getValue() !== "") {
        if (Number($c.stf.getStringSize(txb_AFCHG_ISU_ABBRV1.getValue())) > 1) {
            if (!$c.stf.checkMaxLength(txb_AFCHG_ISU_ABBRV1, 40, "한글종목약명")) return false;
        }
    }
    if (txb_AFCHG_ISU_ENG_NM.getValue() !== "") {
        if (Number($c.stf.getStringSize(txb_AFCHG_ISU_ENG_NM.getValue())) > 1) {
            if (!$c.stf.checkMaxLength(txb_AFCHG_ISU_ENG_NM, 80, "영문종목명")) return false;
        }
    }
    if (txb_AFCHG_ISU_ENG_ABBRV1.getValue() !== "") {
        if (Number($c.stf.getStringSize(txb_AFCHG_ISU_ENG_ABBRV1.getValue())) > 1) {
            if (!$c.stf.checkMaxLength(txb_AFCHG_ISU_ENG_ABBRV1, 40, "영문종목약명")) return false;
        }
    }
    return true;
};

/**
 * @method
 * @name setFormField
 * @description 신규저장,수정하기 전 Form Field Value에 대하여 2바이트 체크 (현업의 미입력에서도 '-' 하이픈을 입력하는 경우가 많아 처리함)
 * @returns {void}
 * @hidden N
 */
scwin.setFormField = function() {
    if (Number($c.stf.getStringSize(txb_AFCHG_ISU_NM.getValue())) === 1) {
        txb_AFCHG_ISU_NM.setValue("");
    }
    if (Number($c.stf.getStringSize(txb_AFCHG_ISU_ABBRV1.getValue())) === 1) {
        txb_AFCHG_ISU_ABBRV1.setValue("");
    }
    if (Number($c.stf.getStringSize(txb_AFCHG_ISU_ENG_NM.getValue())) === 1) {
        txb_AFCHG_ISU_ENG_NM.setValue("");
    }
    if (Number($c.stf.getStringSize(txb_AFCHG_ISU_ENG_ABBRV1.getValue())) === 1) {
        txb_AFCHG_ISU_ENG_ABBRV1.setValue("");
    }
};

/**
 * @method
 * @name save
 * @description 종목명 변경상장 내역 > 신규저장
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    scwin.TR_JOB = 'I';
    if ($c.en.fn_CheckForm() && await scwin.dupCheck()) {
        // Transaction 처리전 안내문구
        if (!$c.lce.fn_isProcess(scwin.TR_JOB)) return;
        if (scwin.vBzProcsNo === undefined || scwin.vBzProcsNo === "") {
            scwin.vBzProcsNo = await $c.stf.getNewBzProcNo(dts_BzProcsNo);
        }
        if (scwin.vBzProcsNo.length !== 14) {
            await $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
        } else {
            await scwin.trs(TRS_IDX_INSERT);
        }
    }
};

/**
 * @method
 * @name parentRefresh
 * @description Parent 화면 Refresh()
 * @returns {void}
 * @hidden N
 */
scwin.parentRefresh = function() {
    // Parent 신청내역 화면 Refresh
    let parentWin = $c.frame.path("../");
    parentWin.txb_SearchIsuCd2.setValue(scwin.vIsuCd);
    parentWin.txb_SearchIsuNm2.setValue(scwin.vIsuAbbrv);
    parentWin.cmb_ISUR_CD2.setValue(scwin.vIsurCd);
    parentWin.fn_list_chglist_appl(scwin.vIsurCd, scwin.vIsuCd);
    parentWin.fn_list_chglist_sync();
};
